file.content:
  flex: 1;
}
.people {
  display: flex;
  gap: 2px;
  flex: none;
}
.who {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--hover);
  font-size: 10px;
  font-weight: 600;
}
details.finding {
  padding: 0;
}
.finding > summary {
  display: block;
  padding: 8px 10px;
  border-radius: 0;
  font-size: 12px;
  font-weight: 400;
  letter-spacing: 0;
  text-transform: none;
  color: var(--fg);
}
.finding > summary::before {
  content: none;
}
.finding-title {
  margin: 4px 0 2px;
}
.finding-body {
  padding: 0 10px 10px;
  font-size: 11px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.finding-body .reason {
  margin-top: 8px;
  padding: 6px 8px;
  border-left: 2px solid var(--tone, var(--border));
  border-radius: 0 4px 4px 0;
  background: var(--hover);
  color: var(--muted);
}
.finding-body .reason b {
  color: var(--tone, var(--fg));
}
.pill {
  flex: none;
  padding: 0 6px;
  border: 1px solid var(--border);
  border-radius: 999px;
  font-size: 10px;
  line-height: 16px;
  color: var(--tone, var(--muted));
}
.heading-row {
  padding: 6px 6px 2px 22px;
}
.sev {
  flex: none;
  padding: 0 5px;
  border: 1px solid var(--border);
  border-radius: 4px;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--tone, var(--muted));
}
.body {
  padding-bottom: 6px;
}

var refreshHint = null
// The worker reads a workspace focus moves to unless the entry this panel shows for it is under a
// minute old (SWITCH_FRESH_MS and shownAt in src/worker), then rewrites the panel. Reading a WSL workspace
// takes up to ~20 seconds; after this long, assume the worker isn't running.
var SWITCH_FRESH_MS = 60000
var CHECK_WAIT_MS = 45000
var focusedKey = null
var checkingSince = null

function readData() {
  try {
    return JSON.parse(document.getElementById('entire-data').textContent)
  } catch (_) {
    return null
  }
}

function el(tag, className, text) {
  var node = document.createElement(tag)
  if (className) node.className = className
  if (text !== undefined && text !== null) node.textContent = String(text)
  return node
}

function add(parent) {
  for (var i = 1; i < arguments.length; i++) if (arguments[i]) parent.appendChild(arguments[i])
  return parent
}

function titled(node, title) {
  if (title) node.title = String(title)
  return node
}

function ago(iso) {
  var seconds = (Date.now() - Date.parse(iso)) / 1000
  if (!isFinite(seconds)) return ''
  if (seconds < 60) return 'just now'
  if (seconds < 3600) return Math.floor(seconds / 60) + ' min ago'
  if (seconds < 86400) return Math.floor(seconds / 3600) + ' h ago'
  return Math.floor(seconds / 86400) + ' d ago'
}

function words(value) {
  return String(value).replace(/_/g, ' ')
}

function plural(count, one, many) {
  return count + ' ' + (count === 1 ? one : many)
}

function step(entry, key) {
  return (entry.steps || []).filter(function (s) {
    return s.key === key
  })[0]
}

function failing(entry) {
  return (
    Boolean(entry.problem) ||
    (entry.steps || []).some(function (s) {
      return !s.ok && !s.optional
    })
  )
}

function health(entry) {
  if (failing(entry)) return 'bad'
  var status = entry.data.status
  return status && !status.enabled ? 'warn' : 'ok'
}

// A <details> that stays open or closed across rerenders, which rebuild the panel every minute.
function disclosure(id, className, openByDefault) {
  var details = el('details', className)
  details.open = Object.prototype.hasOwnProperty.call(opened, id) ? opened[id] : Boolean(openByDefault)
  details.addEventListener('toggle', function () {
    opened[id] = details.open
  })
  return details
}

function section(id, label, count, body, openByDefault) {
  var summary = add(el('summary'), el('span', 'label', label), typeof count === 'string' ? el('span', 'count', count) : count)
  return add(disclosure(id, null, openByDefault), summary, add(el('div', 'body'), body))
}

function row(mark, main, meta, end) {
  return add(el('div', 'row'), mark, add(el('div', 'stack'), main, meta), end)
}

function icon(paths) {
  var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
  svg.setAttribute('viewBox', '0 0 24 24')
  svg.setAttribute('fill', 'none')
  svg.setAttribute('stroke', 'currentColor')
  svg.setAttribute('stroke-width', '2')
  svg.setAttribute('stroke-linecap', 'round')
  svg.setAttribute('stroke-linejoin', 'round')
  paths.forEach(function (d) {
    var path = document.createElementNS('http://www.w3.org/2000/svg', 'path')
    path.setAttribute('d', d)
    svg.appendChild(path)
  })
  return svg
}

function refreshButton() {
  var busy = refreshing || checkingSince !== null
  var button = titled(el('button', 'refresh' + (busy ? ' spinning' : '')), busy ? 'Refreshing…' : 'Refresh')
  button.type = 'button'
  button.setAttribute('aria-label', 'Refresh')
  button.disabled = refreshing
  button.appendChild(icon(['M21 12a9 9 0 1 1-9-9c2.52 0 4.93 1 6.74 2.74L21 8', 'M21 3v5h-5']))
  button.addEventListener('click', requestRefresh)
  return button
}

// The worker hears this notification through Orca's audit log, refreshes, and Orca remounts the
// panel with the new data, which ends this document. Still here later means the worker isn't running.
function requestRefresh() {
  refreshing = true
  refreshHint = null
  rerender()
  orca.host.call('notifications.show', { title: REFRESH_TITLE }).then(
    function () {
      setTimeout(function () {
        refreshing = false
        refreshHint =
          "Nothing refreshed: the plugin's worker isn't running. Run Entire: Refresh panel from the command palette once, and ↻ works until Orca quits."
        rerender()
      }, REFRESH_WAIT_MS)
    },
    function (error) {
      refreshing = false
      refreshHint = "Couldn't ask for a refresh: " + error.code + ': ' + error.message
      rerender()
    }
  )
}

function header(context, entry) {
  var heading = add(el('div', 'heading'), el('span', 'dot ' + (entry ? health(entry) : '')), el('strong', 'clip', context.displayName))
  if (checkingSince !== null) add(heading, el('span', 'when muted', 'Checking…'))
  else if (entry) add(heading, titled(el('span', 'when muted', ago(entry.at)), 'Read from Entire ' + new Date(entry.at).toLocaleString()))
  add(heading, refreshButton())
  var where = entry && entry.workspace.where
  // Orca gives a paired server's workspace no branch; the worker reads it from the server.
  var server = entry && entry.workspace.server
  var branch = context.branch || (server && server.branch) || ''
  return add(
    el('header'),
    heading,
    branch && branch !== context.displayName ? el('div', 'sub mono muted clip', branch) : null,
    where ? titled(el('div', 'sub muted clip', where), where) : null
  )
}

function chips(status) {
  var list = el('div', 'chips')
  add(list, el('span', 'chip ' + (status.enabled ? 'ok' : 'warn'), status.enabled ? 'Enabled' : 'Not enabled'))
  ;(status.agents || []).forEach(function (agent) {
    add(list, el('span', 'chip', agent))
  })
  if (status.unpushed_checkpoints)
    add(list, titled(el('span', 'chip', status.unpushed_checkpoints + ' unpushed'), status.checkpoint_push_policy && words(status.checkpoint_push_policy) + ' push to ' + (status.checkpoint_sync_remote || 'origin')))
  return list
}

function notices(entry) {
  var status = entry.data.status || {}
  var hooks = status.codex_hooks && status.codex_hooks.state
  var list = []
  if (entry.problem) list.push(el('div', 'notice bad', entry.problem))
  if (status.checkpoint_sync_error) list.push(el('div', 'notice bad', 'Checkpoint sync: ' + status.checkpoint_sync_error))
  if (hooks && hooks !== 'ok') list.push(el('div', 'notice warn', 'Codex hooks are ' + words(hooks) + '.'))
  return list
}

function sessions(status) {
  var body = el('div')
  ;(status.active_sessions || []).forEach(function (session) {
    add(
      body,
      row(
        el('span', 'dot ' + (session.status === 'active' ? 'ok' : '')),
        el('div', 'clip', session.agent || 'Agent'),
        el('div', 'meta clip', [session.branch, session.status].filter(Boolean).join(' · ')),
        titled(el('span', 'end clip', session.model), session.model)
      )
    )
  })
  return body
}

function sentence(value) {
  var text = words(value)
  return text.charAt(0).toUpperCase() + text.slice(1)
}

// Gate and check outcomes as a tone: passed, failed, or still to come.
function tone(status, blocking) {
  if (/^(passed|success|completed|approved)$/.test(status)) return 'ok'
  if (/^(failed|failure|error|changes_requested)$/.test(status)) return blocking === false ? 'warn' : 'bad'
  if (/^(running|in_progress|queued)$/.test(status)) return 'warn'
  return ''
}

// Entire's web view marks each gate with a ringed check, cross or dashed ring.
function statusIcon(kind) {
  var ring = 'M12 2a10 10 0 1 0 0 20a10 10 0 1 0 0-20'
  if (kind === 'ok') return icon([ring, 'm8 12 3 3 5-6'])
  if (kind === 'bad' || kind === 'warn') return icon([ring, 'M15 9l-6 6', 'M9 9l6 6'])
  var svg = icon([ring])
  svg.setAttribute('stroke-dasharray', '3 3')
  return svg
}

function person(login) {
  return titled(el('span', 'who', String(login).charAt(0).toUpperCase()), login)
}

// Merged, Ready to merge, Blocked or Not ready, with the line under it.
function mergeState(value) {
  var merge = value.merge
  var blocking = merge
    ? merge.gates.filter(function (gate) {
        return gate.blocking && gate.status === 'failed'
      }).length
    : 0
  if (value.changeStatus === 'merged') return { tone: 'ok', badge: 'Merged', title: 'Merged', line: 'Changes were merged into ' + (value.base || 'the base branch') + '.' }
  if (value.status === 'closed' || value.changeStatus === 'closed') return { tone: '', badge: 'Closed', title: 'Closed', line: 'This change is closed.' }
  if (merge && merge.mergeable) return { tone: 'ok', badge: 'Ready', title: 'Ready to merge', line: 'Every required gate passed.' }
  if (blocking) return { tone: 'bad', badge: 'Blocked', title: 'Blocked', line: plural(blocking, 'gate needs', 'gates need') + ' attention.' }
  return { tone: 'warn', badge: 'Open', title: 'Not ready yet', line: 'Some gates have not finished.' }
}

function trailBadge(value) {
  if (!value) return ''
  var state = mergeState(value)
  return el('span', 'count ' + state.tone, state.badge)
}

function changeCard(value) {
  var who = [value.author, ago(value.mergedAt || value.createdAt)].filter(Boolean).join(' · ')
  var where = add(el('div', 'spread'), add(el('div', 'tags'), value.repository ? titled(el('span', 'tag', value.repository), value.repository) : null, value.change ? el('span', 'tag fixed', '#' + value.change) : null), el('span', 'meta clip', who))
  var branches = add(el('div', 'tags'), value.branch ? titled(el('span', 'tag', value.branch), value.branch) : null, value.base ? el('span', 'muted', '→') : null, value.base ? el('span', 'tag fixed', value.base) : null)
  var diff = value.diff
    ? titled(add(el('span', 'diff'), el('span', 'plus', '+' + value.diff.additions), document.createTextNode(' / '), el('span', 'minus', '−' + value.diff.deletions)), plural(value.diff.files, 'file', 'files') + ' changed')
    : null
  var facts = [value.type && sentence(value.type), value.priority && sentence(value.priority) + ' priority', value.changes.length > 1 ? plural(value.changes.length, 'change', 'changes') : null]
  return add(
    el('div', 'card'),
    add(
      el('div', 'pad'),
      where,
      add(el('div', 'spread gap'), branches, diff),
      titled(el('div', 'name clamp', value.title || 'Untitled trail'), value.title),
      el('div', 'meta', facts.filter(Boolean).join(' · ')),
      value.body ? titled(el('div', 'about clamp', value.body), value.body) : null
    )
  )
}

// One bar segment per reviewer, filled once it finished, red when it found something blocking.
function reviewCard(review) {
  // The worker decides the verdict as Entire's web view does (src/worker/trail.mjs).
  var verdict = {
    pass: { tone: 'ok', text: 'Pass' },
    fail: { tone: 'bad', text: 'Fail' },
    running: { tone: 'warn', text: 'Reviewing' }
  }[review.verdict] || { tone: '', text: 'Not run' }
  var bar = el('div', 'bar')
  var reviewers = review.reviewers.length ? review.reviewers : [null]
  reviewers.forEach(function (reviewer) {
    var found = reviewer ? reviewer.blocking + reviewer.nonBlocking : 0
    var kind = !reviewer ? '' : found ? 'bad' : tone(reviewer.status)
    add(bar, titled(el('span', kind), reviewer && reviewer.name + ': ' + words(reviewer.status) + (found ? ', ' + plural(found, 'finding', 'findings') + (reviewer.blocking ? ' (' + reviewer.blocking + ' blocking)' : ', none blocking') : '')))
  })
  var counts = review.severity
  var found = counts.high + counts.medium + counts.low
  var detail = review.reviewers.length
    ? review.reviewers
        .map(function (reviewer) {
          return reviewer.name
        })
        .join(' · ') + (found ? ' · ' + [counts.high + ' high', counts.medium + ' medium', counts.low + ' low'].join(', ') : ' · nothing found')
    : 'No review has run on this version yet.'
  return add(el('div', 'card'), add(el('div', 'pad'), add(el('div', 'spread'), el('span', 'card-title', 'Code review'), el('span', 'verdict ' + verdict.tone, verdict.text)), bar, el('div', 'meta clip', detail)))
}

function mergeCard(value) {
  var state = mergeState(value)
  var card = add(el('div', 'card'), add(el('div', 'pad'), el('div', 'card-title', state.title), el('div', 'meta', state.line)))
  var merge = value.merge
  if (!merge) return card
  var base = value.base || 'the base branch'
  if (merge.conflicts)
    add(card, gateRow({ key: 'conflicts', status: 'failed', blocking: true, evaluated: true, summary: words(merge.conflicts), rationale: 'Resolve the conflicts with ' + base + ' before merging.', people: [] }, value, base))
  merge.gates.forEach(function (gate) {
    add(card, gateRow(gate, value, base))
  })
  return card
}

// Collapsed: the gate's mark, name, short summary and approvers. Open: what decided it.
function gateRow(gate, value, base) {
  var kind = gate.status === 'passed' ? 'ok' : gate.status === 'failed' ? (gate.blocking ? 'bad' : 'warn') : ''
  var people = el('span', 'people')
  ;(gate.people || []).slice(0, 4).forEach(function (login) {
    add(people, person(login))
  })
  var summary = add(el('summary', 'gate ' + kind), statusIcon(kind), el('span', 'label', sentence(gate.key)), gate.summary ? el('span', 'meta clip', gate.summary) : el('span', 'meta clip'), people)
  var id = 'gate:' + (value.number || '') + ':' + (value.change || '') + ':' + gate.key
  return add(disclosure(id, 'gate-item'), summary, gateBody(gate, base))
}

function gateBody(gate, base) {
  var body = el('div', 'gate-body')
  var detail = gate.detail
  // Up to date's rationale only restates the line its detail shows.
  if (gate.rationale && gate.rationale !== gate.summary && !(detail && gate.type === 'up_to_date')) add(body, el('div', null, gate.rationale))
  if (detail && gate.type === 'approvals') add(body, approvalsDetail(detail))
  else if (detail && gate.type === 'checks') add(body, checksDetail(detail))
  else if (detail && gate.type === 'findings') add(body, findingsGateDetail(detail))
  else if (detail && gate.type === 'up_to_date') add(body, upToDateDetail(detail, base))
  if (gate.staleReason) add(body, el('div', 'facts', 'Stale: ' + gate.staleReason))
