    changes_requested: { tone: 'bad', text: 'Changes requested' },
    commented: { tone: '', text: 'Commented' },
    dismissed: { tone: '', text: 'Dismissed' },
    pending: { tone: 'warn', text: 'Pending' }
  }
  var wrap = el('div')
  var list = el('div', 'list')
  detail.reviewers.forEach(function (reviewer) {
