  return add(wrap, factLine([threshold, severity.high + ' high, ' + severity.medium + ' medium, ' + severity.low + ' low', detail.reviewedHead === false ? 'the latest commit is not reviewed yet' : null]))
}

function upToDateDetail(detail, base) {
  var line = detail.behindBy > 0 ? plural(detail.behindBy, 'commit', 'commits') + ' behind ' + base : detail.compare === 'identical' ? 'Same as ' + base : detail.compare === 'ahead' ? 'Ahead of ' + base + ', nothing missing' : 'Nothing missing from ' + base
