}

function findingsList(findings) {
  var counts = [findings.open + ' open', findings.resolved ? findings.resolved + ' resolved' : null, findings.dismissed ? findings.dismissed + ' dismissed' : null]
  var body = add(el('div'), add(el('div', 'spread heading-row'), el('span', 'card-title', 'Findings'), el('span', 'meta', counts.filter(Boolean).join(' · '))))
  if (!findings.items.length) return add(body, el('div', 'empty', 'No findings on this branch.'))
  findings.items.forEach(function (finding) {
