function findingCard(finding) {
  var severity = finding.severity ? el('span', 'sev ' + (finding.severity === 'high' ? 'bad' : finding.severity === 'medium' ? 'warn' : ''), finding.severity) : null
  var status = finding.status && finding.status !== 'open' ? el('span', 'pill ' + (finding.status === 'resolved' ? 'ok' : ''), sentence(finding.status)) : null
  var stale = finding.stale ? titled(el('span', 'pill', 'Stale'), 'Found on an earlier version of the code') : null
  var confidence = typeof finding.confidence === 'number' ? titled(el('span', 'meta', Math.round(finding.confidence * 100) + '%'), 'Confidence') : null
  var range = finding.line ? ':' + finding.line + (finding.endLine && finding.endLine !== finding.line ? '–' + finding.endLine : '') : ''
