// Orca's plugin frames get no permissions, so the async Clipboard API is refused, but
// execCommand('copy') during a click still works (plugin-frame-session-policies.ts in Orca).
function copyText(text) {
  var area = el('textarea')
  area.value = text
  area.setAttribute('readonly', '')
  area.style.position = 'fixed'
  area.style.top = '-1000px'
  area.style.opacity = '0'
  document.body.appendChild(area)
  area.select()
  var copied = false
  try {
    copied = document.execCommand('copy')
  } catch (_) {}
  document.body.removeChild(area)
  return copied
}

var COPY_ICON = ['M8 8h12v12H8z', 'M16 8V4H4v12h4']
var COPIED_ICON = ['m5 12 5 5L20 7']
var COPY_FAILED_ICON = ['M18 6 6 18', 'M6 6l12 12']

// text is a function so a copy reads what the card shows at the moment of the click.
function copyButton(label, text) {
  var button = titled(el('button', 'copy'), label)
  button.type = 'button'
  button.setAttribute('aria-label', label)
  button.appendChild(icon(COPY_ICON))
  var timer = null
  button.addEventListener('click', function (event) {
    // Inside a <summary>, the click would also open or close the finding.
    event.preventDefault()
    event.stopPropagation()
    var copied = copyText(text())
    button.focus()
    button.className = 'copy ' + (copied ? 'ok' : 'bad')
    button.title = copied ? 'Copied' : "Couldn't copy"
    button.replaceChildren(icon(copied ? COPIED_ICON : COPY_FAILED_ICON))
    clearTimeout(timer)
    timer = setTimeout(function () {
      button.className = 'copy'
      button.title = label
      button.replaceChildren(icon(COPY_ICON))
    }, 1500)
  })
  return button
}

